use verus::prelude::*;

#[requires(true)]
#[ensures(result@.len() == v@.len() + 1)]
#[ensures(forall |i: nat| i < v@.len() ==> result@[i] == v@[i])]
#[ensures(result@[v@.len()] == elem)]
fn append(v: &Vec<u64>, elem: u64) -> Vec<u64> {
    // Pre-allocate a new vector with enough capacity for all elements plus one.
    let mut result = Vec::with_capacity(v.len() + 1);
    // Copy all elements from the input vector.
    result.extend_from_slice(v);
    // Append the new element.
    result.push(elem);
    result
}

